      if(this.approvedConnectorIdentity===undefined||identity.adapterId!==this.approvedConnectorIdentity.adapterId||identity.approvalReference!==this.approvedConnectorIdentity.approvalReference||identity.authorizationIssuer!==this.approvedConnectorIdentity.authorizationIssuer||identity.resourceUri!==this.approvedConnectorIdentity.resourceUri||identity.protocolVersion!==this.approvedConnectorIdentity.protocolVersion)throw new DomainError("BROKER_CONNECTOR_IDENTITY_MISMATCH","Persisted authorization saga does not match the approved connector",403);
